$ErrorActionPreference='Stop';$P=Split-Path -Parent $MyInvocation.MyCommand.Path;if(-not(Test-Path 'angular.json')){throw 'Run from Angular frontend root.'}
$T='src\app\features\admin\content\work-workspace\admin-work-workspace.ts';$H='src\app\features\admin\content\work-workspace\admin-work-workspace.html';foreach($f in @($T,$H)){if(-not(Test-Path $f)){throw "Missing $f"}}
$B=".phase-a4.6b-backup-$(Get-Date -Format yyyyMMdd-HHmmss)";New-Item -ItemType Directory -Force $B|Out-Null;Copy-Item $T $B;Copy-Item $H $B
Copy-Item (Join-Path $P 'payload\src\*') 'src' -Recurse -Force
$t=Get-Content $T -Raw
if($t -notmatch 'AdminContentEditor'){$t=$t -replace "import \{ AdminWorkWorkspaceService \}","import { AdminContentEditor } from './admin-content-editor';`r`nimport { WorkContentDocument, WorkPreviewDocument } from './admin-content-editor.models';`r`nimport { AdminWorkWorkspaceService }";$t=$t -replace 'imports: \[ReactiveFormsModule, RouterLink\]','imports: [ReactiveFormsModule, RouterLink, AdminContentEditor]';$t=$t -replace "readonly workVersionForm = this.fb.nonNullable.group\(\{ title: \['', Validators.required\], summary: \['', Validators.required\], subtitle: \[''\], description: \[''\], contentJson: \['\{\}'\], previewJson: \['\{\}'\] \}\);","readonly versionContent = signal<WorkContentDocument>({ type: 'document', version: 1, blocks: [] });`r`n  readonly versionPreview = signal<WorkPreviewDocument>({ type: 'preview', version: 1, excerpt: '', featuredSections: [], estimatedReadMinutes: 5 });`r`n  readonly workVersionForm = this.fb.nonNullable.group({ title: ['', Validators.required], summary: ['', Validators.required], subtitle: [''], description: [''] });";$t=$t -replace "const value = this.workVersionForm.getRawValue\(\); let content: Record<string, unknown>; let preview: Record<string, unknown>;\s*try \{ content = JSON.parse\(value.contentJson\) as Record<string, unknown>; preview = JSON.parse\(value.previewJson\) as Record<string, unknown>; \}\s*catch \{ this.mutationError.set\('Content or preview JSON is invalid.'\); return; \}","const value = this.workVersionForm.getRawValue(); const content = this.versionContent(); const preview = this.versionPreview();";$t=$t -replace "this.workVersionForm.reset\(\{title:'',summary:'',subtitle:'',description:'',contentJson:'\{\}',previewJson:'\{\}'\}\);","this.workVersionForm.reset({title:'',summary:'',subtitle:'',description:''}); this.versionContent.set({type:'document',version:1,blocks:[]}); this.versionPreview.set({type:'preview',version:1,excerpt:'',featuredSections:[],estimatedReadMinutes:5});";Set-Content $T $t}
$h=Get-Content $H -Raw
$old='<label class="full">Content JSON<textarea rows="7" formControlName="contentJson"></textarea></label><label class="full">Preview JSON<textarea rows="5" formControlName="previewJson"></textarea></label>'
$new='<div class="full"><els-admin-content-editor [initialContent]="versionContent()" [initialPreview]="versionPreview()" (contentChange)="versionContent.set($event)" (previewChange)="versionPreview.set($event)" /></div>'
if(-not $h.Contains($old)){throw 'Exact raw JSON editor markup was not found. Restore from backup and export current files.'};$h=$h.Replace($old,$new);Set-Content $H $h
